x=pd.read_csv(\"respondents.csv\")
def stat(d,v):
 d=d[d[v].notna()]; w=d.wt_final.to_numpy(); y=(d[v].to_numpy()>=4).astype(float); p=np.average(y,weights=w); var=len(d)/(len(d)-1)*np.sum(w*w*(y-p)**2)/sum(w)**2
 return {\"n\":len(d),\"sum_w\":round(sum(w),3),\"effective_n\":round(sum(w)**2/sum(w*w),2),\"distribution_pct\":[round(100*np.sum(w[d[v].to_numpy()==k])/sum(w),2) for k in range(1,6)],\"t2b\":round(100*p,3),\"var\":var}
def pairs(s):
 a=[]
 for l,r in itertools.combinations(s,2):
  dif=s[l][\"t2b\"]-s[r][\"t2b\"]; se=100*np.sqrt(s[l][\"var\"]+s[r][\"var\"]); a.append({\"contrast\":l+\"-\"+r,\"difference_pp\":round(dif,3),\"ci95\":[round(dif-1.96*se,3),round(dif+1.96*se,3)],\"p\":2*norm.sf(abs(dif/se))})
 for z,p in zip(a,multipletests([z[\"p\"] for z in a],method=\"holm\")[1]):z[\"p_holm\"]=float(p)
 return a
out={}
for v in [c for c in x if c.endswith(\"_5\") and c"'!="mealkit_open_5"]:
 s={c:stat(d,v) for c,d in x.groupby("concept")};out[v]={"cells":s,"pairs":pairs(s)}
print(json.dumps(out))
print("SUBGROUPS")
sub={}
for v in ["appeal_5","purchase_intent_5"]:
 sub[v]={str(g):{c:stat(d,v) for c,d in a.groupby("concept")} for g,a in x.groupby("food_explorer")}
 print(v,json.dumps({g:{"cells":s,"pairs":pairs(s)} for g,s in sub[v].items()}))
 ints=[]
 for l,r in itertools.combinations(["Flex","Plus","Simple"],2):
  a,b=sub[v]["1"],sub[v]["0"]; dif=a[l]["t2b"]-a[r]["t2b"]-b[l]["t2b"]+b[r]["t2b"];se=100*np.sqrt(sum(s[c]["var"] for s in [a,b] for c in [l,r]));ints.append({"contrast":l+"-"+r,"interaction_pp":dif,"p":float(2*norm.sf(abs(dif/se)))})
 for z,p in zip(ints,multipletests([z["p"] for z in ints],method="holm")[1]):z["p_holm"]=float(p)
 print("interactions",json.dumps(ints))
print("DIAGNOSTICS")
for c,d in x.groupby("concept"):
 print(c,json.dumps({v:round(100*np.average(d[v],weights=d.wt_final),2) for v in x if v.startswith(("like_","dislike_"))}))
print("AUDIT", {"subgroup_n":x.food_explorer.value_counts().to_dict(),"subgroup_weighted_pct":100*np.average(x.food_explorer,weights=x.wt_final),"route_errors":int(((x.understanding_5>=3)!=x.premium_value_5.notna()).sum()),"subgroup_errors":int((x.food_explorer!=(x[["food_p1","food_p2","food_p3"]].mean(axis=1)>=4).astype(int)).sum()),"ineligible":int((x.mealkit_open_5<3).sum()),"duplicate_ids":int(x.respondent_id.duplicated().sum()),"weight_range":[x.wt_final.min(),x.wt_final.max()]})'"'"

